// ======================= button.h
// One-button gesture detector: short press, long press, double tap.
// Portable C++11, no Arduino dependency, so it runs on the device and in the simulator.
#include <stdint.h>

namespace earshot {

enum class ButtonEvent : uint8_t { None, ShortPress, LongPress, DoubleTap };

struct ButtonTiming {
  uint32_t debounce_ms;        // raw level must hold this long to count
  uint32_t long_press_ms;      // hold this long -> LongPress (fires while still held)
  uint32_t double_tap_gap_ms;  // second press must start within this gap after the first release
  ButtonTiming() : debounce_ms(30), long_press_ms(1500), double_tap_gap_ms(350) {}
};

class Button {
 public:
  explicit Button(ButtonTiming timing = ButtonTiming());

  // Call often (every 20 ms or faster) with the raw button level and the current time.
  // Returns at most one event per call.
  //  - ShortPress is reported once the double-tap window has passed with no second press.
  //  - LongPress is reported the moment the hold threshold is reached; the release is silent.
  //  - DoubleTap is reported on the release of the second tap.
  ButtonEvent update(bool raw_pressed, uint32_t now_ms);

 private:
  ButtonTiming t_;
  bool raw_last_;
  uint32_t raw_changed_at_;
  bool pressed_;
  uint32_t down_at_;
  bool long_fired_;
  bool second_tap_;
  bool tap_pending_;
  uint32_t tap_released_at_;
};

}  // namespace earshot

// ======================= clip_fsm.h
// Consent state machine for the clip, following the PRD:
//   "press to ask consent, hold to stop"
//   ring: off = not listening, amber = asking, green = listening with consent
//
//   NotListening ──press──▶ Asking ──press (patient said yes)──▶ Listening
//        ▲                    │                                      │
//        ├──hold (a "no", logged as a refusal)──┘                    │
//        └────────────────────hold (stop)────────────────────────────┘
//
// NotListening: mic off, ring dark. Nothing is captured.
// Asking:       the medic is asking the patient. Mic still off, ring amber.
// Listening:    consent logged. Mic on, audio streams to the tablet, ring green.
// Double tap while Listening drops a timestamp marker.
// The tablet can drive the same transitions with commands (see protocol.h).
#include <stdint.h>

namespace earshot {

enum class ClipState : uint8_t { NotListening, Asking, Listening };

enum class Input : uint8_t {
  ShortPress,
  LongPress,
  DoubleTap,
  CmdAsk,
  CmdConsentGrant,
  CmdConsentDecline,
  CmdStop,
  CmdMarker
};

enum class Effect : uint8_t {
  None,
  Asked,     // consent ask started
  Granted,   // consent logged: capture starts
  Declined,  // the patient said no (while asking) or withdrew (while listening): capture off
  Stopped,   // the medic or the tablet ended the capture, or cancelled the ask
  Marker
};

struct Transition {
  ClipState next;
  Effect effect;
};

Transition step(ClipState state, Input input);

// Wire names: "not_listening", "asking", "listening".
const char* stateName(ClipState state);

}  // namespace earshot

// ======================= ws_client.h
// Minimal WebSocket client (RFC 6455) over an abstract byte transport.
// The same code runs on the ESP32 (WiFiClient) and in the laptop simulator (POSIX socket).
#include <stddef.h>
#include <stdint.h>
#include <string>
#include <vector>

namespace earshot {

// A connected TCP byte stream. Implemented per platform.
class Transport {
 public:
  virtual ~Transport() {}
  virtual bool connect(const char* host, uint16_t port) = 0;
  virtual bool connected() = 0;
  // Returns bytes written; 0 means the connection failed.
  virtual size_t write(const uint8_t* data, size_t len) = 0;
  // Non-blocking. Returns bytes read, 0 if nothing is waiting, -1 if the peer closed.
  virtual int read(uint8_t* buf, size_t len) = 0;
  virtual void close() = 0;
};

class WsClient {
 public:
  enum class State : uint8_t { Closed, Handshaking, Open };

  WsClient(Transport& transport, uint32_t random_seed);

  // Connects TCP and sends the HTTP upgrade request. The link is usable once state() is Open,
  // which happens inside poll() when the server's 101 response arrives.
  bool open(const char* host, uint16_t port, const char* path);
  void close();

  State state() const { return state_; }
  bool isOpen() const { return state_ == State::Open; }

  // Reads whatever is waiting. Returns true when a complete text message was placed in `out`;
  // call again until it returns false. Pings are answered here.
  bool poll(std::string& out);

  bool sendText(const std::string& text);
  // Sends one binary message made of two parts (header + body) without an extra copy by the caller.
  bool sendBinary(const uint8_t* head, size_t head_len, const uint8_t* body, size_t body_len);

 private:
  bool sendFrame(uint8_t opcode, const uint8_t* a, size_t a_len, const uint8_t* b, size_t b_len);
  bool writeAll(const uint8_t* data, size_t len);
  bool parseFrame(std::string& out);
  uint32_t nextRandom();

  Transport& t_;
  State state_;
  uint32_t rng_;
  std::vector<uint8_t> rx_;
  std::vector<uint8_t> tx_;
  std::string fragment_;
  bool in_fragment_;
};

}  // namespace earshot

// ======================= protocol.h
// Wire protocol between the clip and the tablet gateway (WebSocket, path /clip).
//
// Clip -> tablet, text frames (JSON):
//   {"type":"hello","device":"earshot-clip","fw":"0.3.0","audio":{"rate":16000,"bits":16,"channels":1,"frame_ms":20}}
//   {"type":"state","state":"not_listening|asking|listening","listening":bool,"t_ms":N}
//   {"type":"consent","event":"asked|granted|declined|stopped","source":"button|tablet","t_ms":N}
//   {"type":"marker","id":N,"source":"button|tablet","t_ms":N,"audio_seq":N}
//
//   consent events:
//     asked     the medic started the consent ask (ring amber). Nothing is captured yet.
//     granted   consent logged. Capture starts; audio frames follow.
//     declined  the patient said no while being asked, or withdrew during capture. A refusal.
//     stopped   the medic or the tablet ended the capture, or cancelled the ask.
//
// Clip -> tablet, binary frames (audio, only between "granted" and "declined"/"stopped"):
//   bytes 0..3  uint32 LE  seq    frame counter, restarts at 0 with each "granted";
//                                 a gap means frames were lost
//   bytes 4..7  uint32 LE  t_ms   clip clock when the frame was captured
//   bytes 8..   int16 LE PCM, mono, 16 kHz, 20 ms (320 samples = 640 bytes)
//
// Tablet -> clip, text frames (JSON):
//   {"cmd":"ask"}              start the consent ask
//   {"cmd":"consent_grant"}    log consent and start capture (also valid without a prior ask)
//   {"cmd":"consent_decline"}  log a refusal / withdrawal and stop
//   {"cmd":"stop"}             end the capture
//   {"cmd":"marker"}           drop a timestamp marker (while listening)
//
// t_ms is milliseconds since the clip booted (it has no real-time clock). The tablet should
// stamp wall-clock time on receipt.
#include <stddef.h>
#include <stdint.h>
#include <string>


namespace earshot {

static const uint32_t kSampleRate = 16000;
static const uint32_t kFrameMs = 20;
static const size_t kFrameSamples = 320;  // kSampleRate * kFrameMs / 1000
static const size_t kAudioHeaderBytes = 8;
static const char kFirmwareVersion[] = "0.3.0";

std::string helloJson(const char* device_id);
std::string stateJson(ClipState state, uint32_t t_ms);
std::string consentJson(const char* event, const char* source, uint32_t t_ms);
std::string markerJson(uint32_t id, const char* source, uint32_t t_ms, uint32_t audio_seq);

// Parses a tablet command. Returns false for anything unrecognised.
bool parseCommand(const std::string& json, Input& out);

void putLe32(uint8_t* dst, uint32_t value);

}  // namespace earshot

